module TLATNTSCAX2TS (E, SE, CK, ECK, Q);
  input E, SE, CK, ECK;
  output Q;

  reg Q;

  always @(posedge CK, negedge ECK) begin
    if (!ECK) begin
      Q <= Q;
    end else if (SE) begin
      Q <= 1'b1;
    end else begin
      Q <= E;
    end
  end

endmodule

