    and and0   (and0_out  , A, B    );
    not not0   (not0_out  , B      );
    not not1   (not1_out  , not0_out);
    and and1   (and1_out  , not1_out, C);
    or  or0    (or0_out   , and0_out, and1_out);
    buf buf0   (Y         , or0_out );

