module extclk_generator(
    input clk_in,
    input rst,
    output reg ext_clk
);

reg [3:0] counter;

always @(posedge clk_in, posedge rst) begin
    if (rst) begin
        counter <= 0;
        ext_clk <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == 4) begin
            counter <= 0;
            ext_clk <= ~ext_clk;
        end
    end
end

endmodule

