module counter (
  input clk,
  input reset,
  output reg [3:0] count,
  output reg max_reached
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 4'b0;
      max_reached <= 1'b0;
    end else begin
      count <= count + 1;
      if (count == 4'b1111) begin
        max_reached <= 1'b1;
      end else begin
        max_reached <= 1'b0;
      end
    end
  end

endmodule

