module priority_encoder (
  input clk,
  input reset,
  input [3:0] in,
  output reg [1:0] pos
);

  always @(posedge clk) begin
    if (reset) begin
      pos <= 2'b00;
    end else begin
      casez(in)
        4'b0001: pos <= 2'b00;
        4'b0010: pos <= 2'b01;
        4'b0100: pos <= 2'b10;
        4'b1000: pos <= 2'b11;
        4'b0011, 4'b0111, 4'b1111: pos <= 2'b11;
        4'b0101, 4'b0110, 4'b1011, 4'b1101: pos <= 2'b10;
        4'b1001, 4'b1010, 4'b1100: pos <= 2'b01;
        default: pos <= 2'b00;
      endcase
    end
  end

endmodule

